SourceCode.Declaration:
/// <summary>
/// What kind of counter UserId is (HSMobileOpsUser). The app hides screens accordingly; every counting
/// service enforces the same rules server-side.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountProfileResponse
{
    boolean success;
    str     errorCode;
    boolean isExternalCounter;
    str     counterTeam;
    boolean isCycleCountSupervisor;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('IsExternalCounter')]
public boolean parmIsExternalCounter(boolean _value = isExternalCounter)
{
    isExternalCounter = _value;
    return isExternalCounter;
}

[DataMemberAttribute('CounterTeam')]
public str parmCounterTeam(str _value = counterTeam)
{
    counterTeam = _value;
    return counterTeam;
}

[DataMemberAttribute('IsCycleCountSupervisor')]
public boolean parmIsCycleCountSupervisor(boolean _value = isCycleCountSupervisor)
{
    isCycleCountSupervisor = _value;
    return isCycleCountSupervisor;
}
